import{c as t,Q as a,j as o,m as d}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"REST API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rest-api.md","filePath":"reference/rest-api.md","lastUpdated":1780984191000}'),n={name:"reference/rest-api.md"};function s(r,e,i,c,p,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h1><p>VideoNode exposes a Huma-generated REST API. The authoritative schema is served by the running daemon. This page is a pointer, not a copy.</p><table tabindex="0"><thead><tr><th>Where</th><th>What</th></tr></thead><tbody><tr><td><code>http://&lt;host&gt;:8090/docs</code></td><td>Interactive API reference rendered by <a href="https://stoplight.io/open-source/elements" target="_blank" rel="noreferrer">Stoplight Elements</a></td></tr><tr><td><code>http://&lt;host&gt;:8090/openapi.json</code></td><td>Machine-readable OpenAPI 3 description (JSON)</td></tr><tr><td><code>http://&lt;host&gt;:8090/openapi.yaml</code></td><td>Same description in YAML</td></tr></tbody></table><p>Use those for endpoint shapes, request/response schemas, and authentication details. The schema is always in sync with the daemon you&#39;re hitting; this static page would not be.</p><h2 id="snapshot-and-preview-endpoints" tabindex="-1">Snapshot and preview endpoints <a class="header-anchor" href="#snapshot-and-preview-endpoints" aria-label="Permalink to &quot;Snapshot and preview endpoints&quot;">​</a></h2><p>Each source and composer exposes two image endpoints outside the Huma schema:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Returns</th></tr></thead><tbody><tr><td><code>GET /api/sources/{id}/snapshot.jpg</code></td><td>Latest cached JPEG frame from the producer (sets an <code>ETag</code>)</td></tr><tr><td><code>GET /api/sources/{id}/preview.mjpg</code></td><td>Live multipart MJPEG stream</td></tr><tr><td><code>GET /api/composers/{id}/snapshot.jpg</code></td><td>Latest cached JPEG of the canvas</td></tr><tr><td><code>GET /api/composers/{id}/preview.mjpg</code></td><td>Live multipart MJPEG stream</td></tr></tbody></table><h2 id="operational-endpoints" tabindex="-1">Operational endpoints <a class="header-anchor" href="#operational-endpoints" aria-label="Permalink to &quot;Operational endpoints&quot;">​</a></h2><p>The daemon also serves <code>/api/health</code>, <code>/metrics</code>, <code>/api/options</code>, <code>/api/devices</code>, <code>/api/encoders</code>, <code>/api/pipeline</code>, <code>/api/leds</code>, <code>/api/processes</code>, and <code>/api/metrics</code>. Their request and response shapes are described in <code>/openapi.json</code>; this page does not duplicate them.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>All endpoints except <code>/api/health</code> and <code>/metrics</code> require either Linux account auth (default) or basic auth, depending on the daemon&#39;s <code>auth.type</code> setting. See <a href="./../getting-started/installation#web-ui-authentication">Installation – Web UI authentication</a> for the user/group setup, or <a href="./config-toml#auth">config.toml reference</a> to switch to basic credentials.</p><h2 id="server-sent-events" tabindex="-1">Server-Sent Events <a class="header-anchor" href="#server-sent-events" aria-label="Permalink to &quot;Server-Sent Events&quot;">​</a></h2><p>Live state updates are pushed on the <code>/api/events</code> SSE channel. See <a href="./../development/events-and-sse">Events and SSE</a> for the event model, or <a href="./../operating/observability#consuming-sse-events">Observability</a> to consume the stream.</p>',13)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
